// ============================================================
// ContactIn – Admin Global JS
// Shared helpers for all modules
// ============================================================

(function($){
    'use strict';

    /** ============================
     * Message Box helper
     * ============================ */
    window.cinShowMessage = function(text, type = 'info', timeout = 4000) {
        $('#cin-message-box').remove();

        // Check for message_box config in various localized objects
        const msgBoxConfig = window.cinInbox?.i18n?.message_box 
                          || window.ContactINEmailLog?.i18n?.message_box
                          || window.cinRestLog?.i18n?.message_box
                          || window.contactinCrmLog?.i18n?.message_box;

        const $box = $('<div id="cin-message-box" class="cin-message-box"></div>')
            .addClass(type)
            .attr('role', 'alert')
            .text(text);

        const $pageHeader = $('.wrap .cin-page-header').first();
        const $heading = $('.wrap h1, .wrap h1.wp-heading-inline');

        if ($pageHeader.length) {
            $pageHeader.after($box);
        } else if ($heading.length) {
            $heading.after($box);
        } else {
            $('.wrap').prepend($box);
        }

        if (timeout > 0) {
            setTimeout(() => $box.fadeOut(400, () => $box.remove()), timeout);
        }
    };

    /** ============================
     * Central AJAX handler (generic)
     * ============================ */
    window.cinAjax = function(action, data = {}, successCallback, errorCallback, config = {}) {
        const ajaxUrl = config.ajax_url || cinInbox?.ajax_url || window.ajaxurl;
        const nonce   = config.nonce   || cinInbox?.nonce;

        const params = new URLSearchParams();
        params.set('action', action);
        if (nonce) params.set('nonce', nonce);

        Object.entries(data).forEach(([key, value]) => {
            if (value === null || value === undefined || value === '' || value === false) return;
            if (Array.isArray(value)) {
                value.forEach(v => params.append(`${key}[]`, v));
            } else {
                params.set(key, value);
            }
        });

        return fetch(ajaxUrl, {
            method: 'POST',
            credentials: 'same-origin',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
                'X-Requested-With': 'XMLHttpRequest'
            },
            body: params.toString()
        })
        .then(r => {
            if (!r.ok) throw new Error(`HTTP ${r.status}`);
            return r.json();
        })
        .then(res => {
            if (res.success) {
                if (typeof successCallback === 'function') successCallback(res);
            } else {
                const msg = (res.data && res.data.message)
                    ? res.data.message
                    : (config.i18n?.progress?.error || 'Error');
                cinShowMessage(msg, 'error');
            }
            return res; 
        })
        .catch(err => {
            console.error('CIN AJAX failed:', err);
            if (typeof errorCallback === 'function') {
                errorCallback(err);
            } else {
                cinShowMessage(config.i18n?.progress?.error || 'Error', 'error');
            }
            throw err; 
        });
    };

    /** ============================
     * Export Helper (chunked downloads)
     * Reusable across inbox, logs, etc.
     * options: {
     *   infoAction: 'ci_export_info', // AJAX action to fetch totals/limit
     *   baseUrl: 'admin-ajax.php?action=ci_export_csv&...', // download URL with nonce & filters
     *   search: '',
     *   status: 'all',
     *   ajax_url: '...', // optional ajax URL
     *   nonce: '...'     // optional nonce
     * }
     * ============================ */
    window.cinExportHelper = function(options = {}) {
        const infoAction = options.infoAction || 'ci_export_info';
        const baseUrl    = options.baseUrl || '';
        const search     = options.search || '';
        const status     = options.status || 'all';
        const contactId  = options.contact_id || 0;
        const ajax_url   = options.ajax_url || window.cinInbox?.ajax_url || window.ContactINEmailLog?.ajax_url || window.contactinCrmLog?.ajaxUrl || window.ContactINRestLog?.ajax_url || window.ajaxurl;
        const nonce      = options.nonce || window.cinInbox?.nonce || window.ContactINEmailLog?.nonce || window.contactinCrmLog?.nonce || window.ContactINRestLog?.nonce;

        if (!baseUrl) {
            cinShowMessage('Export URL missing.', 'error');
            return;
        }

        cinAjax(infoAction, { 
            s: search, 
            status: status, 
            contact_id: contactId,
            crm_status: options.crm_status || '',
            deletion_status: options.deletion_status || ''
        }, function(res) {
            if (!res.success || !res.data) {
                cinShowMessage('Failed to prepare export.', 'error');
                return;
            }

            const total   = res.data.total || 0;
            const maxCap  = res.data.limit || 1000;
            const batches = res.data.batches || 1;

            if (!total) {
                cinShowMessage('No records to export.', 'info');
                return;
            }

            // Use existing modal template from page
            const modalId = 'cin-export-modal';
            const $modal = $('#' + modalId);
            
            if (!$modal.length) {
                cinShowMessage('Export modal not found.', 'error');
                return;
            }

            // Update modal with dynamic values
            $('#cin-export-total').text(total);
            $('#cin-export-max').text(maxCap);
            $('#cin-export-chunk').attr('max', maxCap).val(Math.min(maxCap, 500));
            $('#cin-export-links').empty();

            // Show modal with fade in
            $modal.addClass('active');
            setTimeout(() => {
                document.getElementById('cin-export-chunk')?.focus();
            }, 10);

            let buildTimer = null;

            function setChunkDisabled(state) {
                $('#cin-export-chunk').prop('disabled', !!state);
            }

            function showLinksLoading() {
                setChunkDisabled(true);
                $('#cin-export-links').html('<div style="display:flex;align-items:center;gap:8px;padding:8px 4px;font-size:13px;color:#444;"><span class="dashicons dashicons-update dashicons-spin"></span><span>Preparing download links...</span></div>');
            }

            function buildLinks(chunkSize) {
                chunkSize = Math.max(1, Math.min(maxCap, chunkSize || maxCap));
                const totalBatches = Math.max(1, Math.ceil(total / chunkSize));
                const $container = $('#cin-export-links');
                const links = [];
                for (let i = 0; i < totalBatches; i++) {
                    const start = i * chunkSize + 1;
                    const end = Math.min(total, (i + 1) * chunkSize);
                    const url = `${baseUrl}&batch=${i + 1}&limit=${chunkSize}&total_batches=${totalBatches}`;
                    links.push(`<div style="margin:4px 0;"><a class="cin-export-link" href="${url}" data-batch="${i+1}" data-chunk="${chunkSize}">Download ${start}–${end}</a></div>`);
                }
                $container.html(links.join(''));
                setChunkDisabled(false);
            }

            const $chunkInput = $('#cin-export-chunk');
            function scheduleBuild(immediate = false) {
                if (buildTimer) clearTimeout(buildTimer);
                const run = () => {
                    const chunk = parseInt($chunkInput.val(), 10) || maxCap;
                    showLinksLoading();
                    // Small delay to let the spinner paint before building links
                    setTimeout(() => buildLinks(chunk), 180);
                };
                if (immediate) {
                    run();
                } else {
                    buildTimer = setTimeout(run, 400);
                }
            }

            scheduleBuild(true);

            // Close button handler
            const handleCloseClick = function(e) {
                if (buildTimer) clearTimeout(buildTimer);
                $modal.removeClass('active');
            };

            // Overlay click to close (click on dark background)
            const handleOverlayClick = function(e) {
                if (e.target.id === 'cin-export-modal') {
                    if (buildTimer) clearTimeout(buildTimer);
                    $modal.removeClass('active');
                }
            };

            // Download link click handler
            const handleDownloadClick = function(e) {
                e.preventDefault();
                const url = $(this).attr('href');
                triggerCSVDownload(url);
            };

            // Chunk size change/keyup handler
            const handleChunkChange = function(e) {
                if (e.type === 'keyup' && e.key !== 'Enter') {
                    scheduleBuild(false);
                    return;
                }
                scheduleBuild(true);
            };

            // Attach event handlers
            $modal.on('click', '#cin-export-close', handleCloseClick);
            $modal.on('click', handleOverlayClick);
            $modal.on('click', '.cin-export-link', handleDownloadClick);
            $modal.on('change keyup', '#cin-export-chunk', handleChunkChange);
        }, function() {
            cinShowMessage('Failed to export records.', 'error');
        }, {
            ajax_url: ajax_url,
            nonce:    nonce,
            nonce_key: 'nonce',
            timeout:  15000,
            i18n:     window.cinInbox?.i18n || window.ContactINEmailLog?.i18n || window.contactinCrmLog?.i18n || window.ContactINRestLog?.i18n || {}
        });
    };

    function triggerCSVDownload(url) {
        const iframe = document.createElement('iframe');
        iframe.style.display = 'none';
        iframe.src = url;
        document.body.appendChild(iframe);
        setTimeout(() => {
            iframe.remove();
        }, 15000);
    }

    /** ============================
     * Auto-submit helper for log filters
     * ============================ */
    window.cinAttachAutoSubmit = function(config = {}) {
        const formSelector = config.form;
        const fields = config.fields || [];
        if (!formSelector || !fields.length) return;
        const $form = $(formSelector);
        if (!$form.length) return;
        fields.forEach(selector => {
            const $el = $(selector);
            if (!$el.length) return;
            $el.on('change', () => $form.trigger('submit'));
        });
    };

    /** ============================
     * Select All checkboxes
     * ============================ */
    $(document).on('change', '#cb-select-all-1, #cb-select-all-2', function () {
        const checked = this.checked;
        $('input[name="message_ids[]"]').prop('checked', checked);
    });

    // Page-specific auto-submit bindings for log pages
    $(function() {
        window.cinAttachAutoSubmit({
            form: '#contactin-email-log-form',
            fields: ['#status-filter', '#per-page-filter-email']
        });

        window.cinAttachAutoSubmit({
            form: '#contactin-crm-log-form',
            fields: ['#status-filter-crm', '#operation-filter-crm', '#per-page-filter-crm']
        });

        window.cinAttachAutoSubmit({
            form: '#contactin-rest-log-form',
            fields: ['#method-filter', '#endpoint-filter', '#http-code-filter', '#validated-filter', '#per-page-filter-rest']
        });
    });

    /** ============================
     * Help modal manager
     * ============================ */
    const HELP_MODAL_ATTR = 'data-cin-help-modal';
    const HELP_TRIGGER_ATTR = 'data-cin-help-open';
    const FOCUSABLE_SELECTOR = 'a[href]:not([tabindex="-1"]), button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])';
    const scheduleFocus = window.requestAnimationFrame
        ? window.requestAnimationFrame.bind(window)
        : (cb) => setTimeout(cb, 0);
    const openStack = [];
    const focusHandlers = new WeakMap();
    const triggerRestore = new WeakMap();
    let bodyOverflowCache = '';

    function lockBodyScroll() {
        if (!document.body || openStack.length > 0) {
            return;
        }
        bodyOverflowCache = document.body.style.overflow || '';
        document.body.style.overflow = 'hidden';
    }

    function unlockBodyScroll() {
        if (!document.body) {
            return;
        }

        if (openStack.length === 0) {
            document.body.style.overflow = bodyOverflowCache;
        }
    }

    function setInitialFocus(modal) {
        const focusTarget = modal.querySelector('[data-cin-help-focus]')
            || modal.querySelector('.cin-modal-close')
            || modal.querySelector(FOCUSABLE_SELECTOR);

        if (focusTarget && typeof focusTarget.focus === 'function') {
            scheduleFocus(() => focusTarget.focus());
        }
    }

    function bindFocusTrap(modal) {
        if (focusHandlers.has(modal)) {
            return;
        }

        const handler = (event) => {
            if (event.key !== 'Tab') {
                return;
            }
            const focusable = modal.querySelectorAll(FOCUSABLE_SELECTOR);
            if (!focusable.length) {
                event.preventDefault();
                return;
            }

            const first = focusable[0];
            const last = focusable[focusable.length - 1];

            if (event.shiftKey && document.activeElement === first) {
                event.preventDefault();
                last.focus();
            } else if (!event.shiftKey && document.activeElement === last) {
                event.preventDefault();
                first.focus();
            }
        };

        modal.addEventListener('keydown', handler);
        focusHandlers.set(modal, handler);
    }

    function unbindFocusTrap(modal) {
        const handler = focusHandlers.get(modal);
        if (handler) {
            modal.removeEventListener('keydown', handler);
            focusHandlers.delete(modal);
        }
    }

    function closeModal(modal) {
        if (!modal || modal.classList.contains('cin-modal-hidden')) {
            return;
        }

        registerModal(modal);

        modal.classList.add('cin-modal-hidden');
        modal.setAttribute('aria-hidden', 'true');
        unbindFocusTrap(modal);

        const index = openStack.indexOf(modal);
        if (index > -1) {
            openStack.splice(index, 1);
        }

        if (!openStack.length) {
            unlockBodyScroll();
        }

        const trigger = triggerRestore.get(modal);
        if (trigger && typeof trigger.focus === 'function') {
            trigger.focus();
        }
        triggerRestore.delete(modal);
    }

    function openModal(modal, options = {}) {
        if (!modal) {
            return;
        }

        registerModal(modal);

        if (!modal.classList.contains('cin-modal-hidden')) {
            return;
        }

        lockBodyScroll();
        modal.classList.remove('cin-modal-hidden');
        modal.setAttribute('aria-hidden', 'false');
        if (!modal.hasAttribute('role')) {
            modal.setAttribute('role', 'dialog');
        }
        modal.setAttribute('aria-modal', 'true');

        openStack.push(modal);
        bindFocusTrap(modal);
        setInitialFocus(modal);

        if (options.trigger) {
            triggerRestore.set(modal, options.trigger);
        }
    }

    function scrollToSection(modal, targetId) {
        if (!targetId || targetId.charAt(0) !== '#') {
            return;
        }

        const section = modal.querySelector(targetId);
        if (!section) {
            return;
        }

        const bodyEl = modal.querySelector('.cin-modal-body');
        if (bodyEl) {
            const containerRect = bodyEl.getBoundingClientRect();
            const targetRect = section.getBoundingClientRect();
            const offset = targetRect.top - containerRect.top + bodyEl.scrollTop - 12;
            if (typeof bodyEl.scrollTo === 'function') {
                bodyEl.scrollTo({ top: offset, behavior: 'smooth' });
            } else {
                bodyEl.scrollTop = offset;
            }
        } else {
            section.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function registerModal(modal) {
        if (!modal || modal.dataset.cinHelpBound === '1') {
            return;
        }

        modal.dataset.cinHelpBound = '1';
        modal.setAttribute('aria-hidden', modal.classList.contains('cin-modal-hidden') ? 'true' : 'false');
        if (!modal.hasAttribute('role')) {
            modal.setAttribute('role', 'dialog');
        }
        modal.setAttribute('aria-modal', 'true');

        const overlay = modal.querySelector('.cin-modal-overlay');
        const dismissButtons = modal.querySelectorAll('.cin-modal-close, .cin-modal-dismiss');
        const navLinks = modal.querySelectorAll('.cin-help-link');

        dismissButtons.forEach((btn) => {
            btn.addEventListener('click', (event) => {
                event.preventDefault();
                closeModal(modal);
            });
        });

        if (overlay) {
            overlay.addEventListener('click', () => closeModal(modal));
        }

        modal.addEventListener('click', (event) => {
            if (event.target === modal) {
                closeModal(modal);
            }
        });

        navLinks.forEach((link) => {
            link.addEventListener('click', (event) => {
                const href = link.getAttribute('href');
                if (!href || href.charAt(0) !== '#') {
                    return;
                }
                event.preventDefault();
                scrollToSection(modal, href);
            });
        });
    }

    function registerTrigger(trigger) {
        if (!trigger || trigger.dataset.cinHelpTrigger === '1') {
            return;
        }

        trigger.dataset.cinHelpTrigger = '1';
        trigger.addEventListener('click', (event) => {
            const targetId = trigger.getAttribute(HELP_TRIGGER_ATTR);
            if (!targetId) {
                return;
            }

            event.preventDefault();
            const modal = document.getElementById(targetId);
            if (!modal) {
                return;
            }

            registerModal(modal);
            openModal(modal, { trigger });
        });
    }

    function initHelpModals() {
        const modals = document.querySelectorAll('.cin-modal[' + HELP_MODAL_ATTR + ']');
        modals.forEach(registerModal);

        const triggers = document.querySelectorAll('[' + HELP_TRIGGER_ATTR + ']');
        triggers.forEach(registerTrigger);

        document.addEventListener('keydown', (event) => {
            if (event.key === 'Escape' && openStack.length) {
                const last = openStack[openStack.length - 1];
                closeModal(last);
            }
        });
    }

    $(initHelpModals);

    window.ContactINHelpModals = {
        open: (id) => openModal(document.getElementById(id)),
        close: (id) => closeModal(document.getElementById(id)),
        refresh: () => {
            document.querySelectorAll('.cin-modal[' + HELP_MODAL_ATTR + ']').forEach(registerModal);
            document.querySelectorAll('[' + HELP_TRIGGER_ATTR + ']').forEach(registerTrigger);
        }
    };

    const helpCompatibilityMap = {
        openCinHelpModal: 'cin-help-modal',
        openCinCrmHelpModal: 'cin-crm-help-modal',
        openCinInboxHelpModal: 'cin-inbox-help-modal',
        openCinRestApiHelpModal: 'cin-restapi-help-modal',
        openCinMaintHelpModal: 'contactin-maint-help-modal'
    };

    Object.entries(helpCompatibilityMap).forEach(([fnName, modalId]) => {
        window[fnName] = () => window.ContactINHelpModals.open(modalId);
    });

    /** ============================
     * Toggle Button Utilities
     * Gold Standard Enable/Disable Button Styles
     * ============================ */
    
    // Inject toggle button styles if not already present
    if (!document.getElementById('cin-toggle-button-styles')) {
        const style = document.createElement('style');
        style.id = 'cin-toggle-button-styles';
        style.textContent = `
            /* Gold Standard Toggle Button Styles */
            .button.button-small.enabled {
                background: #00a32a;
                color: #fff;
                border-color: #008a20;
            }
            .button.button-small.enabled:hover {
                background: #008a20;
                border-color: #007017;
            }
            .cin-status-label {
                font-weight: 600;
                padding: 4px 10px;
                border-radius: 3px;
                font-size: 12px;
                display: inline-block;
                margin-left: 10px;
            }
            .cin-status-label.enabled {
                color: #00a32a;
                background: #f0f6f0;
            }
            .cin-status-label.disabled {
                color: #d63638;
                background: #fcf0f1;
            }
        `;
        document.head.appendChild(style);
    }

    /**
     * Initialize a toggle button with gold standard styling
     * @param {Object} config - Configuration object
     * @param {string} config.buttonId - ID of the toggle button
     * @param {string} config.statusLabelId - ID of the status label
     * @param {string} config.hiddenFieldId - ID of the hidden input field
     * @param {string} config.ajaxAction - AJAX action name
     * @param {string} config.enabledText - Text when enabled (e.g., "Disable SMTP")
     * @param {string} config.disabledText - Text when disabled (e.g., "Enable SMTP")
     * @param {string} config.enabledLabel - Status label when enabled (e.g., "Enabled")
     * @param {string} config.disabledLabel - Status label when disabled (e.g., "Disabled")
     * @param {Function} config.onToggle - Optional callback after successful toggle
     */
    window.cinInitToggleButton = function(config) {
        const {
            buttonId,
            statusLabelId,
            hiddenFieldId,
            ajaxAction,
            enabledText,
            disabledText,
            enabledLabel = 'Enabled',
            disabledLabel = 'Disabled',
            onToggle
        } = config;

        const $button = $('#' + buttonId);
        const $statusLabel = $('#' + statusLabelId);
        const $hiddenField = $('#' + hiddenFieldId);

        if (!$button.length) return;

        function setBusy(isBusy) {
            $button.prop('disabled', isBusy);
            $button.toggleClass('cin-toggle-busy', isBusy);
        }

        // Update button and label UI
        function updateUI(enabled) {
            // Update button
            $button.text(enabled ? enabledText : disabledText);
            $button.toggleClass('enabled', enabled);
            $button.data('enabled', enabled ? '1' : '0');

            // Update status label
            if ($statusLabel.length) {
                $statusLabel.text(enabled ? enabledLabel : disabledLabel);
                $statusLabel.removeClass('enabled disabled').addClass(enabled ? 'enabled' : 'disabled');
            }

            // Update hidden field
            if ($hiddenField.length) {
                $hiddenField.val(enabled ? '1' : '0');
            }

            // Call custom callback
            if (typeof onToggle === 'function') {
                onToggle(enabled);
            }
        }

        // Initialize button state on page load
        const initialEnabled = $button.data('enabled') === 1 || $button.data('enabled') === '1';
        updateUI(initialEnabled);

        // Handle toggle click
        $button.off('click').on('click', function() {
            const currentEnabled = $button.data('enabled') === 1 || $button.data('enabled') === '1';
            const newEnabled = !currentEnabled;

            setBusy(true);

            $.post(ajaxurl, {
                action: ajaxAction,
                enabled: newEnabled ? 1 : 0,
                nonce: window.contactinbox_admin?.nonce || window.cinInbox?.nonce || window.contactinIntegrationL10n?.nonce || window.cinCRMSettings?.nonce
            }, function(response) {
                if (response && response.success) {
                    setBusy(false);
                    updateUI(newEnabled);
                    cinShowMessage(response.data?.message || 'Settings updated successfully', 'success', 3000);
                } else if (response?.data?.requires_confirmation) {
                    setBusy(false);

                    const modal = document.getElementById('contactin-restapi-disable-modal');
                    const messageText = response.data.message || 'Disabling REST API will also disable file attachments.';

                    if (!modal) {
                        const fallback = messageText + '\n\nDo you want to disable the REST API service anyway?';
                        if (confirm(fallback)) {
                            setBusy(true);
                            $.post(ajaxurl, {
                                action: ajaxAction,
                                enabled: newEnabled ? 1 : 0,
                                force_disable: '1',
                                nonce: window.contactinbox_admin?.nonce || window.cinInbox?.nonce || window.contactinIntegrationL10n?.nonce || window.cinCRMSettings?.nonce
                            }, function(retryResponse) {
                                setBusy(false);
                                if (retryResponse && retryResponse.success) {
                                    updateUI(newEnabled);
                                    cinShowMessage(retryResponse.data?.message || 'REST API service disabled successfully', 'success', 3000);
                                } else {
                                    cinShowMessage(retryResponse.data?.message || 'Failed to update settings', 'error', 5000);
                                }
                            }).fail(function() {
                                setBusy(false);
                                cinShowMessage('Network error. Please try again.', 'error', 5000);
                            });
                        } else {
                            updateUI(currentEnabled);
                        }
                        return;
                    }

                    const messageEl = document.getElementById('contactin-restapi-disable-message');
                    if (messageEl) {
                        messageEl.textContent = messageText;
                    }

                    const confirmBtn = modal.querySelector('#contactin-restapi-disable-confirm');
                    const cancelBtn = modal.querySelector('#contactin-restapi-disable-cancel');
                    const closeBtns = modal.querySelectorAll('.cin-modal-close');
                    const overlay = modal.querySelector('.cin-modal-overlay');

                    const teardown = () => {
                        if (confirmBtn) confirmBtn.removeEventListener('click', onConfirm);
                        if (cancelBtn) cancelBtn.removeEventListener('click', onCancel);
                        closeBtns.forEach((btn) => btn.removeEventListener('click', onCancel));
                        if (overlay) overlay.removeEventListener('click', onCancel);
                    };

                    const onCancel = (event) => {
                        if (event && typeof event.preventDefault === 'function') {
                            event.preventDefault();
                        }
                        teardown();
                        closeModal(modal);
                        updateUI(currentEnabled);
                    };

                    const onConfirm = (event) => {
                        if (event && typeof event.preventDefault === 'function') {
                            event.preventDefault();
                        }
                        teardown();
                        closeModal(modal);
                        setBusy(true);

                        $.post(ajaxurl, {
                            action: ajaxAction,
                            enabled: newEnabled ? 1 : 0,
                            force_disable: '1',
                            nonce: window.contactinbox_admin?.nonce || window.cinInbox?.nonce || window.contactinIntegrationL10n?.nonce || window.cinCRMSettings?.nonce
                        }, function(retryResponse) {
                            setBusy(false);
                            if (retryResponse && retryResponse.success) {
                                updateUI(newEnabled);
                                cinShowMessage(retryResponse.data?.message || 'REST API service disabled successfully', 'success', 3000);
                            } else {
                                cinShowMessage(retryResponse.data?.message || 'Failed to update settings', 'error', 5000);
                            }
                        }).fail(function() {
                            setBusy(false);
                            cinShowMessage('Network error. Please try again.', 'error', 5000);
                        });
                    };

                    if (confirmBtn) confirmBtn.addEventListener('click', onConfirm);
                    if (cancelBtn) cancelBtn.addEventListener('click', onCancel);
                    closeBtns.forEach((btn) => btn.addEventListener('click', onCancel));
                    if (overlay) overlay.addEventListener('click', onCancel);

                    registerModal(modal);
                    openModal(modal, { trigger: $button[0] });
                } else {
                    setBusy(false);
                    cinShowMessage(response?.data?.message || 'Failed to update settings', 'error', 5000);
                }
            }).fail(function() {
                setBusy(false);
                cinShowMessage('Network error. Please try again.', 'error', 5000);
            });
        });
    };

    /**
     * Quick helper to create a toggle button HTML
     * @param {Object} config - Configuration
     * @returns {string} HTML string
     */
    window.cinCreateToggleButtonHTML = function(config) {
        const {
            buttonId,
            statusLabelId,
            hiddenFieldId,
            enabled = false,
            enabledText = 'Disable',
            disabledText = 'Enable',
            enabledLabel = 'Enabled',
            disabledLabel = 'Disabled',
            fieldName
        } = config;

        return `
            <div class="cin-toggle-control">
                ${hiddenFieldId && fieldName ? `<input type="hidden" name="${fieldName}" id="${hiddenFieldId}" value="${enabled ? '1' : '0'}" />` : ''}
                <button type="button" 
                    id="${buttonId}" 
                    class="button button-small${enabled ? ' enabled' : ''}" 
                    data-enabled="${enabled ? '1' : '0'}">
                    ${enabled ? enabledText : disabledText}
                </button>
                ${statusLabelId ? `<span id="${statusLabelId}" class="cin-status-label ${enabled ? 'enabled' : 'disabled'}">
                    ${enabled ? enabledLabel : disabledLabel}
                </span>` : ''}
            </div>
        `;
    };

})(jQuery);
